import {WEAPONS,starterWeaponIndex} from './game-logic.js';
const $=s=>document.querySelector(s),screen=$('#screen');
const paths={objective:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3"/>',pause:'<path d="M8 5v14M16 5v14"/>',shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6Z"/>',health:'<path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6Z"/>',swap:'<path d="M4 7h15m-4-4 4 4-4 4M20 17H5m4-4-4 4 4 4"/>',aim:'<circle cx="12" cy="12" r="7"/><path d="M12 2v6m0 8v6M2 12h6m8 0h6"/>',jump:'<path d="m5 13 7-7 7 7m-14 6 7-7 7 7"/>',fire:'<path d="m6 18 12-12m-8-1h9v9M4 13l7 7"/>',crouch:'<circle cx="14" cy="5" r="2"/><path d="m12 9-3 5h7l3 5M9 14l-4 5m9-9 5 3M4 21h16"/>',melee:'<path d="M6 12V7a2 2 0 0 1 4 0V6a2 2 0 0 1 4 0v1a2 2 0 0 1 4 0v5m-8-3v3m4-3v3M6 11l-2 1v4l4 5h8l4-6v-3l-3-1-4 3-3-2Z"/>',charge:'<circle cx="12" cy="13" r="7"/><path d="M10 3h4m-2 0v3m2 4-4 4h4l-3 4"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',interact:'<path d="M8 21V10a2 2 0 0 1 4 0v3m0-4V5a2 2 0 0 1 4 0v8m0-4a2 2 0 0 1 4 0v7l-3 5H8l-4-7a2 2 0 0 1 3-2l1 1"/>',sprint:'<circle cx="15" cy="4" r="2"/><path d="m12 8-4 4 5 3-2 6m1-13 4 5h5M9 10l-4 2m8 3 5 5M2 6h6M1 9h4"/>'};
for(const node of document.querySelectorAll('[data-icon]'))node.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true">'+paths[node.dataset.icon]+'</svg>';
const proposals={dock:{title:'A · Dock adaptatif',description:'Le meilleur compromis pour jouer : les informations restent proches des commandes, avec une zone centrale largement dégagée.',points:['À gauche : santé et bouclier au-dessus du joystick.','À droite : un seul compteur de munitions ; toucher le nombre recharge, toucher les flèches change d’arme.','Tir, visée et saut accessibles immédiatement. Charge et mêlée regroupées au-dessus du tir.','Course en poussant le joystick à fond ; interaction seulement près d’un élément utilisable.']},ribbon:{title:'B · Bandeau compact',description:'Toutes les informations vitales sont regroupées sur une seule surface. Pratique si tu préfères lire un tableau de bord sans chercher à gauche et à droite.',points:['Santé, bouclier et munitions dans un bandeau unique.','Les commandes tactiles restent aux mêmes endroits que dans A.','Sur Mac : bandeau en bas au centre, sans boutons tactiles.','Lecture très rapide ; le bandeau occupe davantage le haut de l’écran sur iPhone.']},minimal:{title:'C · Immersion',description:'La proposition la plus discrète. Elle conserve les informations essentielles et range les actions secondaires dans une palette.',points:['Mission réduite à une pastille ; santé, bouclier et munitions toujours présents.','Tir, visée et saut restent directs. Le bouton « … » ouvre charge, mêlée et posture.','Le menu d’actions ne masque pas les informations vitales.','Moins de boutons permanents ; une pression de plus pour une charge ou une mêlée.']}};
let state={hero:'lylu',solution:'minimal',device:'portrait',weapon:6,hp:100,shield:60,charges:2,ammo:8,paused:false},toastTimer,reloadTimer,previousFocus;
function render(){const w=WEAPONS[state.weapon];$('#health').textContent=state.hp;$('#shield').textContent=state.shield;$('#ammo').textContent=state.ammo;$('#capacity').textContent='/ '+w.capacity;$('#weapon-name').textContent=w.name;screen.style.setProperty('--shield',state.shield/60*100+'%');for(const node of document.querySelectorAll('.charge-count'))node.textContent=state.charges;screen.classList.toggle('critical',state.hp<30);}
function toast(message){const node=$('.toast');node.textContent=message;node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,1500);}
function closeMore(){screen.classList.remove('more-open');$('.quick-menu').hidden=true;$('[data-action=more]').setAttribute('aria-expanded','false');}
function pause(value){state.paused=value;$('.pause-overlay').hidden=!value;screen.classList.toggle('paused',value);if(value){previousFocus=document.activeElement;$('.pause-panel button').focus();}else previousFocus?.focus();}
function chooseSolution(solution){state.solution=solution;screen.dataset.solution=solution;for(const b of document.querySelectorAll('[data-solution][role=tab]'))b.setAttribute('aria-selected',String(b.dataset.solution===solution));const p=proposals[solution];$('#proposal-title').textContent=p.title;$('#proposal-description').textContent=p.description;$('#proposal-points').innerHTML=p.points.map(t=>'<li>'+t+'</li>').join('');closeMore();}
function reload(){const w=WEAPONS[state.weapon];if(state.ammo===w.capacity){toast('Chargeur plein');return;}if(reloadTimer)return;$('#weapon-name').textContent='RECHARGE';reloadTimer=setTimeout(()=>{state.ammo=w.capacity;reloadTimer=null;render();},900);}
function reset(){clearTimeout(reloadTimer);reloadTimer=null;state={...state,weapon:starterWeaponIndex(state.hero),hp:100,shield:60,charges:2};state.ammo=WEAPONS[state.weapon].capacity;screen.classList.remove('taking-damage');render();}
function action(name,event){if(state.paused&&!['resume','settings','vr','home'].includes(name))return;
 if(name==='objective'){const node=$('.objective');node.hidden=!node.hidden;$('[data-action=objective]').setAttribute('aria-expanded',String(!node.hidden));}
 else if(name==='pause'||name==='resume')pause(name==='pause');
 else if(name==='settings'){pause(false);$('#opaque').checked=!$('#opaque').checked;document.body.classList.toggle('opaque',$('#opaque').checked);toast('Contraste '+($('#opaque').checked?'renforcé':'standard'));}
 else if(name==='vr')toast('Aperçu du menu : l’accès VR reste disponible ici dans tous les modes.');
 else if(name==='home'){pause(false);document.querySelector('.page-head').scrollIntoView({behavior:'smooth'});}
 else if(name==='fire'){if(reloadTimer)return;if(state.ammo>0){state.ammo--;render();}if(state.ammo===0)reload();}
 else if(name==='reload')reload();
 else if(name==='weapon'){const order=[starterWeaponIndex(state.hero),1,2],i=order.indexOf(state.weapon);state.weapon=order[(i+1)%order.length];state.ammo=WEAPONS[state.weapon].capacity;render();toast(WEAPONS[state.weapon].name);}
 else if(name==='charge'){if(state.charges>0){state.charges--;render();toast('Charge lancée');}else toast('Aucune charge disponible');closeMore();}
 else if(name==='melee'){toast('Frappe de mêlée');closeMore();}
 else if(name==='aim'||name==='crouch'){const button=event?.target.closest('button');button?.setAttribute('aria-pressed',String(button.getAttribute('aria-pressed')!=='true'));screen.classList.toggle(name==='aim'?'aiming':'crouching');if(name==='crouch')closeMore();}
 else if(name==='jump')toast('Saut');
 else if(name==='sprint'){toast('Course');closeMore();}
 else if(name==='interact'){toast('Archives locales consultées');$('.context').hidden=true;$('#context-demo').setAttribute('aria-pressed','false');}
 else if(name==='more'){const open=!screen.classList.contains('more-open');screen.classList.toggle('more-open',open);$('.quick-menu').hidden=!open;$('[data-action=more]').setAttribute('aria-expanded',String(open));}
}
for(const button of document.querySelectorAll('[data-action]'))button.addEventListener('click',e=>action(button.dataset.action,e));
for(const b of document.querySelectorAll('[role=tab]'))b.onclick=()=>chooseSolution(b.dataset.solution);
$('#device').onchange=event=>{state.device=event.target.value;screen.dataset.device=state.device;closeMore();$('#dimensions').textContent=({portrait:'iPhone · portrait',landscape:'iPhone · paysage',mac:'Mac · clavier / manette'})[state.device];$('.preview-caption span:last-child').textContent=state.device==='mac'?'Aucun bouton tactile ; raccourcis discrets':'Déplacement à gauche · caméra par glissement à droite';};
$('#lighting').onchange=e=>screen.dataset.light=e.target.value;
$('#hero').onchange=e=>{state.hero=e.target.value;screen.dataset.hero=state.hero;reset();};
$('#opaque').onchange=e=>document.body.classList.toggle('opaque',e.target.checked);
$('#damage-demo').onclick=()=>{const damage=27,held=Math.min(state.shield,damage);state.shield-=held;state.hp=Math.max(0,state.hp-(damage-held));screen.classList.add('taking-damage');setTimeout(()=>screen.classList.remove('taking-damage'),1000);render();};
$('#context-demo').onclick=()=>{const n=$('.context');n.hidden=!n.hidden;$('#context-demo').setAttribute('aria-pressed',String(!n.hidden));};
$('#reset-demo').onclick=reset;
const stick=$('.move-ring'),knob=$('.move-knob');let drag=null;
stick.addEventListener('pointerdown',e=>{drag=e.pointerId;stick.setPointerCapture(e.pointerId);e.preventDefault();});stick.addEventListener('pointermove',e=>{if(drag!==e.pointerId)return;const r=stick.getBoundingClientRect(),x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2,n=Math.max(1,Math.hypot(x,y)/28);knob.style.transform='translate('+x/n+'px,'+y/n+'px)';$('.sprint-hint').textContent=y<-25?'COURSE':'COURIR ↑';});for(const event of ['pointerup','pointercancel'])stick.addEventListener(event,()=>{drag=null;knob.style.transform='';$('.sprint-hint').textContent='COURIR ↑';});
document.addEventListener('keydown',e=>{if(e.code==='Escape'){pause(!state.paused);return;}if(state.paused&&e.code==='Tab'){const buttons=[...document.querySelectorAll('.pause-panel button')],i=buttons.indexOf(document.activeElement);e.preventDefault();buttons[(i+(e.shiftKey?-1:1)+buttons.length)%buttons.length].focus();return;}if(document.activeElement?.matches('button,input,select'))return;const command={Space:'fire',KeyR:'reload',KeyB:'charge',KeyX:'melee'}[e.code];if(command){e.preventDefault();action(command);}});
chooseSolution('minimal');render();
window.__PINKWAR_HUD_PREVIEW={snapshot:()=>({...state}),chooseSolution,reset};
